\set ON_ERROR_STOP on
\copy (WITH ordinary AS (SELECT pg_table_size('practo.appointments'::regclass) AS table_bytes, pg_indexes_size('practo.appointments'::regclass) AS index_bytes), partitioned AS (SELECT sum(pg_table_size(relid)) AS table_bytes, sum(pg_indexes_size(relid)) AS index_bytes FROM pg_partition_tree('practo.appointments_partitioned'::regclass) WHERE isleaf) SELECT current_database() AS database_name, pg_database_size(current_database()) AS database_bytes, ordinary.table_bytes AS ordinary_table_bytes, ordinary.index_bytes AS ordinary_index_bytes, ordinary.table_bytes + ordinary.index_bytes AS ordinary_total_bytes, partitioned.table_bytes AS partitioned_leaf_table_bytes, partitioned.index_bytes AS partitioned_leaf_index_bytes, partitioned.table_bytes + partitioned.index_bytes AS partitioned_leaf_total_bytes FROM ordinary CROSS JOIN partitioned) TO 'benchmarks/results/large/partition_storage.csv' WITH (FORMAT CSV, HEADER TRUE);
